#!/usr/bin/env python3
"""Combine authored integration contracts with executed measurements; writes only this folder."""
import hashlib
import json
import pathlib
import subprocess

HERE = pathlib.Path(__file__).resolve().parent
REPO = HERE.parents[2]
measured_bytes = (HERE / 'measurements.json').read_bytes()
measured = json.loads(measured_bytes)
REV = measured['sourceRevision']
source = subprocess.check_output(['git', 'show', f'{REV}:src/parts/city.ts'], cwd=REPO).decode()

def line(text):
    assert text in source, text
    return source[:source.index(text)].count('\n') + 1

