    d['measured'] = {k:m[k] for k in ['layoutRadius','restSolidsBody','sampledSweepSolidsBody','sampledSweepArtBody','staticArtBody','staticMembers','groups','terminals','canonicalPlacements','sampling','terminalDiagnostics']}
    assert len(d['measured']['terminals']) == 2
    devices.append(d)

